await page.goto('https://www.apache.org/');
await cu.click('License');
return await page.evaluate(() => cu.claim({key_text: 'Apache License, Version 2.0', answer: document.querySelector('h1')?.innerText || document.title}));

await page.goto('https://www.iban.com/');
await cu.click('Currency Codes');
await page.getByText('Japan', { exact: true }).first();
await page.evaluate(() => cu.claim({key_text: 'Japan', answer: cu.text('Japan')}));

await page.goto('https://www.iban.com/currency-codes');
await page.getByText('Japan', { exact: true }).first();
await page.evaluate(() => cu.claim({key_text: 'Japan', answer: (() => { const rows = [...document.querySelectorAll('tr')]; const row = rows.find(r => r.innerText.trim().startsWith('Japan')); return row ? row.innerText.trim().split(/\s+/)[1] : ''; })()}));

await page.goto('https://www.nist.gov/pml/owm/metric-si');
